python3 -c "
import html.parser as h
class P(h.HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ('br','img','meta','link','input','hr','source','area','base','col','embed','param','track','wbr','path','rect','circle','ellipse','line','polyline','polygon','stop','use','defs'):
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f'mismatch close {tag}, stack tail: {self.stack[-3:]}')
import sys
for f in ['index.html','experience.html','lineup.html','map.html','tickets.html']:
    p = P()
    p.feed(open(f).read())
    if p.errors or p.stack:
        print(f, 'errors:', p.errors[:5], 'remaining:', p.stack[-5:])
    else:
        print(f, 'OK')
" 2>&1 | head -50
